    "model": "gpt-oss:20b",
    "messages": [
        {
            "role": "user",
            "content": "devide 54354 by 9943 using tools\n"
        }
    ],
    "stream": true,
    "options": {
        "temperature": 0.1
    },
    "format": "json",
    "tools": [
        {
            "type": "function",
            "function": {
                "name": "python",
                "description": "Execute arbitrary Python code with 'eval' and return result. ",
                "parameters": {
